import{_ as l,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Performance Meeting 2021-08-12","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-08-12","date":"2021-08-12T00:00:00.000Z","updated":"2021-08-21T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","回滚","BlueFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-08-12.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-08-12.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Performance_Meeting_2021-08-12.md"};function o(s,e,n,p,u,g){return i(),a("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>日期：</strong> 2021年8月12日 <strong>参会人员：</strong> Casey, Mark, Igor, Adam, Niha, Josh, Gabby 等</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>RGW对象缓存PR讨论</strong></p><ul><li>Casey提出一个关于RGW对象缓存的PR，旨在作为重构前的临时解决方案。讨论了该PR的潜在价值，但需要更多数据支持。</li></ul></li><li><p><strong>BlueFS日志增量更新模式</strong></p><ul><li>讨论了减少BlueFS日志增长速度的增量更新模式，提出了两个PR，最终将选择一个进行合并。</li></ul></li><li><p><strong>调试构建变更的回滚</strong></p><ul><li>讨论了回滚导致混淆的调试构建变更。</li></ul></li><li><p><strong>延迟IO路径的改进</strong></p><ul><li>讨论了优化硬盘驱动器上延迟IO路径的PR，以减少写放大。提出了多个PR，旨在优化这一过程。</li></ul></li><li><p><strong>MDS锁切换到公平互斥锁</strong></p><ul><li>讨论了将MDS锁切换到公平互斥锁的PR，请求Patrick进行审查。</li></ul></li><li><p><strong>其他PR和更新</strong></p><ul><li>讨论了多个其他PR，包括RGW跟踪、Radix优化、BlueFS精细锁定等，以及需要重新审查和测试的PR。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>同意将Igor的PR应用于master和Pacific版本，以改进延迟IO路径。</li><li>同意进行更多测试，特别是针对硬盘驱动器的性能测试，以更好地理解写放大问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Casey将继续推动RGW对象缓存PR的审查和测试。</li><li>团队将继续审查和测试BlueFS日志增量更新模式的PR。</li><li>将进行更多针对硬盘驱动器的性能测试，以验证和优化延迟IO路径的改进。</li><li>继续跟踪和审查其他PR，确保所有变更都经过充分的测试和审查。</li></ul><p><strong>下次会议：</strong> 下周</p><p><strong>备注：</strong> 会议超时，但所有议题均得到充分讨论。</p><p><strong>改进说明：</strong></p><ol><li>保留了会议的关键细节，包括日期、参会人员和讨论的主要议题。</li><li>确保了会议的决定事项和后续行动计划得到反映。</li><li>保留了Ceph相关领域的英文原文关键词，如Ceph, distributed storage, CRUSH algorithm, high availability, scalability等。</li><li>优化了总结的清晰度和准确性。</li></ol>',12)])])}const _=l(r,[["render",o]]);export{d as __pageData,_ as default};
